input.command:
Write-Output "=== entire start times ==="; Get-Process entire | Select-Object Id, StartTime, CPU, WorkingSet64 | Format-Table -AutoSize; Write-Output "=== parents ==="; Get-CimInstance Win32_Process -Filter "Name = 'entire.exe' OR Name = 'git.exe' OR Name = 'sh.exe' OR Name = 'bash.exe'" | Select-Object ProcessId, ParentProcessId, Name, CreationDate | Format-Table -AutoSize; Write-Output "=== index locks ==="; Get-ChildItem -Path "D:\Documents\vscode" -Recurse -Force -Filter "index.lock" -ErrorAction SilentlyContinue | Select-Object FullName, LastWriteTime, Length; Write-Output "=== shortcut details ==="; $sh = New-Object -ComObject WScript.Shell; foreach ($p in @(
  "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Cursor.lnk",
  "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Cursor\Cursor.lnk"
)) { $s = $sh.CreateShortcut($p); Write-Output "---- $p"; Write-Output "Target: $($s.TargetPath)"; Write-Output "Args: $($s.Arguments)"; Write-Output "Icon: $($s.IconLocation)"; Write-Output "WorkDir: $($s.WorkingDirectory)" }

$ico = "C:\Users\Administrator\AppData\Local\Programs\cursor\resources\app\resources\win32\code.ico,0"
$sh = New-Object -ComObject WScript.Shell
$targets = @(
  "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Cursor.lnk",
  "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Cursor\Cursor.lnk"
)
$pinDir = "$env:APPDATA\Microsoft\Internet Explorer\Quick Launch\User Pinned\TaskBar"
if (Test-Path $pinDir) {
  Get-ChildItem $pinDir -Filter "*.lnk" | ForEach-Object {
    $s = $sh.CreateShortcut($_.FullName)
    if ($s.TargetPath -match "Cursor.exe$") { $targets += $_.FullName }
  }
}
foreach ($p in $targets) {
  $s = $sh.CreateShortcut($p)
  $s.IconLocation = $ico
  $s.Save()
  $check = $sh.CreateShortcut($p)
  Write-Output "$p -> $($check.IconLocation)"
}
& ie4uinit.exe -show
Write-Output "icon cache refresh requested"

$roots = Get-ChildItem "D:\Documents\vscode" -Directory -ErrorAction SilentlyContinue
foreach ($r in $roots) {
  $hooksJson = Join-Path $r.FullName ".cursor\hooks.json"
  $settings = Join-Path $r.FullName ".entire\settings.json"
  $prep = Join-Path $r.FullName ".git\hooks\prepare-commit-msg"
  $hasCursor = Test-Path $hooksJson
  $hasSettings = Test-Path $settings
  $hasPrep = $false
  $stdinClosed = $false
  if (Test-Path $prep) {
    $text = Get-Content $prep -Raw
    if ($text -match "entire hooks git") { $hasPrep = $true; if ($text -match "</dev/null") { $stdinClosed = $true } }
  }
  if ($hasCursor -or $hasSettings -or $hasPrep) {
    Write-Output ("{0} | cursor-hooks={1} | entire-settings={2} | git-hook={3} | stdin-closed={4}" -f $r.Name, $hasCursor, $hasSettings, $hasPrep, $stdinClosed)
  }
}

Write-Output "=== still hung? ==="; Get-Process -Id 30840,31096 -ErrorAction SilentlyContinue | Select-Object Id, CPU, StartTime; Write-Output "=== configure help ==="; entire configure --help; Write-Output "=== local settings files ==="; Get-ChildItem "D:\Documents\vscode\houdini-wizard\.entire" -Force | Select-Object Name, Length, LastWriteTime; Write-Output "=== user entire config ==="; @(
  "$env:USERPROFILE\.entire",
  "$env:APPDATA\entire",
  "$env:LOCALAPPDATA\entire"
) | ForEach-Object { if (Test-Path $_) { Write-Output "EXISTS $_"; Get-ChildItem $_ -Force | Select-Object Name } else { Write-Output "missing $_" } }
